package io.github.diodeme.ji.extension;

import java.nio.charset.StandardCharsets;
import java.util.Objects;

/** Adapter from one already-trusted, ready data resource to a prompt contribution. */
public final class ResourcePromptContributor implements PromptContributor {
    private final ContributorId id;
    private final ResourceSource.LoadedResource resource;
    private final int priority;
    private final int tokenBudget;

    public ResourcePromptContributor(String id, ResourceSource.LoadedResource resource, int priority, int tokenBudget) {
        this.id = new ContributorId(id);
        this.resource = Objects.requireNonNull(resource, "resource");
        if (resource.descriptor().kind() == ResourceDescriptor.ResourceKind.EXTENSION) {
            throw new IllegalArgumentException("extension resources cannot be prompt contributors");
        }
        this.priority = priority;
        if (tokenBudget < 0) throw new IllegalArgumentException("tokenBudget must not be negative");
        this.tokenBudget = tokenBudget;
    }

    @Override public ContributorId id() { return id; }

    @Override public ResourceDescriptor.SourceId source() { return resource.descriptor().source(); }

    @Override public int priority() { return priority; }

    @Override public int tokenBudget() { return tokenBudget; }

    @Override
    public Contribution contribute(PromptContext context) {
        context.cancellation().throwIfCancellationRequested();
        return new Contribution(new String(resource.content(), StandardCharsets.UTF_8));
    }
}
